# Arabic titles and one-line rules for the 102 Term-1 learning outcomes of Grades 11-12 (General / Advanced).
# (title_ar, rule_summary (EN), rule_ar). Titles in English come from the supplied bank (data/bank.json).
META = {
'11G': {
 1: ('التمدد ومعامل المقياس', 'Image = scale factor × original coordinates (center at the origin). k>1 enlarges, 0<k<1 reduces.', 'إحداثيات الصورة = معامل المقياس × إحداثيات الأصل (المركز نقطة الأصل). k>1 تكبير و0<k<1 تصغير.'),
 2: ('التناسب في المضلعات المتشابهة', 'Similar polygons have equal corresponding angles and proportional corresponding sides.', 'المضلعات المتشابهة زواياها المتناظرة متطابقة وأضلاعها المتناظرة متناسبة.'),
 3: ('تشابه المثلثات بمسلمة AA', 'Two pairs of equal angles are enough to prove two triangles similar (AA).', 'يكفي تطابق زاويتين في المثلثين لإثبات التشابه (AA).'),
 4: ('تشابه المثلثات: AA وSSS وSAS', 'Choose AA, SSS or SAS: SSS needs three equal ratios, SAS needs two equal ratios with the included angle.', 'اختر AA أو SSS أو SAS: SSS ثلاث نسب متساوية، وSAS نسبتان متساويتان مع الزاوية المحصورة.'),
 5: ('تشابه المثلثات: AA وSSS وSAS', 'Use the similarity to write proportions between corresponding sides, then solve for the unknown.', 'استخدم التشابه لكتابة تناسب بين الأضلاع المتناظرة ثم حل لإيجاد المجهول.'),
 6: ('الأجزاء المتناسبة في المثلثات', 'A line parallel to one side divides the other two sides proportionally; the converse also holds.', 'المستقيم الموازي لضلع يقسم الضلعين الآخرين بنسب متناسبة، والعكس صحيح.'),
 7: ('منصفات وارتفاعات ومتوسطات متناظرة', 'In similar triangles, corresponding bisectors, altitudes and medians have the same ratio as the sides.', 'في المثلثات المتشابهة تكون نسبة المنصفات والارتفاعات والمتوسطات المتناظرة مثل نسبة الأضلاع.'),
 8: ('الوسط الهندسي', 'Geometric mean of a and b is √(ab). Altitude to the hypotenuse: h² = (segment 1)(segment 2).', 'الوسط الهندسي للعددين a وb هو √(ab). الارتفاع على الوتر: h² = حاصل ضرب القطعتين.'),
 9: ('نظرية فيثاغورس', 'In a right triangle a²+b²=c², where c is the hypotenuse.', 'في المثلث القائم a²+b²=c² حيث c الوتر.'),
 10: ('تطبيقات نظرية فيثاغورس', 'Draw the right triangle hidden in the situation, label legs and hypotenuse, then apply a²+b²=c².', 'ارسم المثلث القائم في المسألة وحدد الضلعين والوتر ثم طبّق a²+b²=c².'),
 11: ('المسافة بين نقطتين', 'd = √((x₂−x₁)²+(y₂−y₁)²).', 'المسافة d = √((x₂−x₁)²+(y₂−y₁)²).'),
 12: ('مثلثات 45°–45°–90°', 'Sides are in ratio 1 : 1 : √2. Hypotenuse = leg × √2.', 'النسبة بين الأضلاع 1 : 1 : √2. الوتر = الضلع × √2.'),
 13: ('مثلثات 30°–60°–90°', 'Sides are in ratio 1 : √3 : 2 (short leg, long leg, hypotenuse).', 'النسبة بين الأضلاع 1 : √3 : 2 (الضلع القصير، الطويل، الوتر).'),
 14: ('النسب المثلثية: الأضلاع والزوايا', 'sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent. Use the inverse key to find an angle.', 'sin = المقابل/الوتر، cos = المجاور/الوتر، tan = المقابل/المجاور. استخدم المعكوس لإيجاد الزاوية.'),
 15: ('تطبيقات النسب المثلثية', 'Sketch the right triangle, choose the ratio that links the known and unknown sides, solve.', 'ارسم المثلث القائم واختر النسبة التي تربط المعلوم بالمجهول ثم حل.'),
 16: ('تمثيل فضاء العينة', 'List all outcomes with a table, tree diagram or organised list.', 'اكتب جميع النواتج بجدول أو شجرة أو قائمة منظمة.'),
 17: ('مبدأ العد الأساسي', 'If choices are made in stages, multiply the number of options at each stage.', 'عند الاختيار على مراحل اضرب عدد الخيارات في كل مرحلة.'),
 18: ('الحوادث المستقلة والمعتمدة', 'Independent: P(A and B)=P(A)·P(B). Dependent: P(A and B)=P(A)·P(B given A).', 'مستقلة: P(A∩B)=P(A)·P(B). معتمدة: P(A∩B)=P(A)·P(B|A).'),
 19: ('الاحتمال الشرطي', 'P(B | A) = P(A and B) / P(A).', 'P(B|A) = P(A∩B) / P(A).'),
 20: ('الحوادث المتنافية وغير المتنافية', 'Mutually exclusive: P(A or B)=P(A)+P(B). Otherwise subtract the overlap: P(A)+P(B)−P(A and B).', 'متنافية: P(A∪B)=P(A)+P(B). غير ذلك اطرح التقاطع: P(A)+P(B)−P(A∩B).'),
 21: ('خصائص المضلعات المتشابهة', 'Scale factor = ratio of corresponding sides; perimeters have the same ratio, areas the square of it.', 'معامل المقياس = نسبة الأضلاع المتناظرة؛ المحيطات بالنسبة نفسها والمساحات بمربعها.'),
 22: ('الأجزاء المتناسبة في المثلثات', 'Write the proportion of the divided sides and compare ratios to test parallelism.', 'اكتب تناسب الأجزاء وقارن النسب لاختبار التوازي.'),
 23: ('النسب المثلثية: المحيط والمساحة', 'Find missing sides with sin/cos/tan, then use P = sum of sides and A = ½·b·h.', 'أوجد الأضلاع المجهولة بالنسب المثلثية ثم استخدم المحيط = مجموع الأضلاع والمساحة = ½·ق·ع.'),
 24: ('زاويتا الارتفاع والانخفاض', 'Angles of elevation/depression are measured from the horizontal; draw the right triangle and use tan.', 'تقاس زاويتا الارتفاع والانخفاض من الأفقي؛ ارسم المثلث القائم واستخدم tan.'),
 25: ('الاحتمالات المعتمدة والمستقلة', 'Check whether the first draw changes the second: with replacement events are independent.', 'تحقق هل يؤثر السحب الأول في الثاني: مع الإرجاع تكون الحوادث مستقلة.'),
 26: ('الاحتمالات المتنافية وغير المتنافية', 'P(A or B)=P(A)+P(B)−P(A and B); the overlap is 0 only for mutually exclusive events.', 'P(A∪B)=P(A)+P(B)−P(A∩B)؛ يكون التقاطع صفراً فقط للحوادث المتنافية.'),
},
'11A': {
 1: ('رسم دوال النمو الأسي', 'For y=a·bˣ with b>1 the graph rises, passes through (0,a) and has the x-axis as asymptote.', 'للدالة y=a·bˣ مع b>1 يرتفع المنحنى ويمر بالنقطة (0,a) ومحور السينات خط تقارب.'),
 2: ('حل المتباينات الأسية', 'Write both sides with the same base, then compare exponents (reverse the sign if 0<b<1).', 'اكتب الطرفين بالأساس نفسه ثم قارن الأسس (اعكس الإشارة إذا كان 0<b<1).'),
 3: ('تحويل الصيغ الأسية واللوغاريتمية', 'log_b a = c ⇔ bᶜ = a (b>0, b≠1, a>0).', 'log_b a = c ⇔ bᶜ = a (b>0، b≠1، a>0).'),
 4: ('حل معادلات لوغاريتمية بالخصائص', 'Use log a + log b = log(ab), log a − log b = log(a/b), log aⁿ = n·log a, then remove the logs and check the domain.', 'استخدم خصائص اللوغاريتم لدمج الحدود ثم أزل اللوغاريتم وتحقق من المجال.'),
 5: ('صيغة تغيير الأساس', 'log_b a = log a / log b = ln a / ln b.', 'log_b a = log a / log b = ln a / ln b.'),
 6: ('الأساس الطبيعي واللوغاريتم الطبيعي', 'ln x is log base e; ln eˣ = x and e^(ln x) = x.', 'ln x لوغاريتم الأساس e؛ ln eˣ = x وe^(ln x) = x.'),
 7: ('تبسيط العبارات النسبية', 'Factor numerator and denominator, cancel common factors, and state excluded values.', 'حلّل البسط والمقام واختصر العوامل المشتركة وبيّن القيم المستثناة.'),
 8: ('تبسيط الكسور الجبرية المركبة', 'Multiply numerator and denominator by the LCD of all inner fractions.', 'اضرب البسط والمقام في المضاعف المشترك الأصغر لمقامات الكسور الداخلية.'),
 9: ('تحويلات الدوال المقلوبة', 'y = a/(x−h) + k: asymptotes x=h and y=k; a stretches/reflects.', 'y = a/(x−h) + k: خطا التقارب x=h وy=k؛ والمعامل a يمدّد/يعكس.'),
 10: ('حل المعادلات النسبية', 'Multiply by the LCD, solve, then reject any root that makes a denominator zero.', 'اضرب في المضاعف المشترك الأصغر وحل ثم استبعد أي جذر يجعل المقام صفراً.'),
 11: ('تصنيف أنواع الدراسات الإحصائية', 'Survey, observational study, experiment (treatments imposed), simulation: decide who assigns the treatment.', 'مسح، دراسة رصدية، تجربة (تُفرض المعالجة)، محاكاة: حدّد من يُعيّن المعالجة.'),
 12: ('الاحتمال التجريبي والنظري', 'Experimental = successes ÷ trials; theoretical = favourable outcomes ÷ all equally likely outcomes.', 'التجريبي = عدد النجاحات ÷ عدد المحاولات؛ النظري = النواتج المرغوبة ÷ جميع النواتج المتساوية.'),
 13: ('تصميم محاكاة احتمالية', 'Assign digits so the simulated chances match the real probabilities, then repeat many trials.', 'وزّع الأرقام بحيث تطابق الاحتمالات المحاكاة ثم كرّر التجربة مرات كثيرة.'),
 14: ('التوزيع: المركز والتشتت والشكل', 'Describe centre (mean/median), spread (range, IQR, SD) and shape (symmetric, skewed).', 'صف المركز (الوسط/الوسيط) والتشتت (المدى، IQR، الانحراف) والشكل (متماثل، ملتو).'),
 15: ('الزوايا في الوضع القياسي', 'Standard position: vertex at the origin, initial side on the positive x-axis; coterminal angles differ by 360°.', 'الوضع القياسي: الرأس عند الأصل والضلع الابتدائي على محور السينات الموجب؛ الزوايا المشتركة تختلف بمضاعفات 360°.'),
 16: ('قيم النسب المثلثية', 'Use the reference angle and the quadrant to find the value and sign of sin, cos, tan.', 'استخدم الزاوية المرجعية والربع لإيجاد قيمة وإشارة sin وcos وtan.'),
 17: ('خصائص الدوال الدورية', 'Period, amplitude and midline: A = (max−min)/2, midline = (max+min)/2.', 'الدورة والسعة وخط المنتصف: السعة = (أكبر−أصغر)/2، وخط المنتصف = (أكبر+أصغر)/2.'),
 18: ('تطبيقات الدوال الجيبية', 'Model with y = A sin(B(x−C)) + D; period = 2π/B.', 'النمذجة y = A sin(B(x−C)) + D؛ الدورة = 2π/B.'),
 19: ('الدوال المثلثية الأخرى', 'csc = 1/sin, sec = 1/cos, cot = 1/tan; tan = sin/cos.', 'csc = 1/sin وsec = 1/cos وcot = 1/tan؛ وtan = sin/cos.'),
 20: ('الدوال المثلثية العكسية', 'sin⁻¹, cos⁻¹, tan⁻¹ return an angle in the principal range: [−90°,90°], [0°,180°], (−90°,90°).', 'تعيد sin⁻¹ وcos⁻¹ وtan⁻¹ زاوية في المدى الأساسي: [−90°،90°] و[0°،180°] و(−90°،90°).'),
 21: ('عبارات الأساس الطبيعي واللوغاريتم الطبيعي', 'Domain of eˣ is ℝ, range (0,∞); average rate of change = (f(b)−f(a))/(b−a).', 'مجال eˣ هو ℝ ومداها (0,∞)؛ متوسط التغير = (f(b)−f(a))/(b−a).'),
 22: ('النمو والتضاؤل الأسي باللوغاريتمات', 'Half-life T: k = ln 2 / T and y = a·e^(−kt).', 'نصف العمر T: k = ln 2 / T وy = a·e^(−kt).'),
 23: ('الدوال النسبية: المقارب المائل والثقوب', 'Divide when deg(top) = deg(bottom)+1 to get the oblique asymptote; a cancelled factor gives a hole.', 'اقسم عندما درجة البسط = درجة المقام + 1 لإيجاد المقارب المائل؛ العامل المختصر يعطي ثقباً.'),
 24: ('الاحتمالات الطبيعية والمساحات والقيم العكسية', 'z = (x−μ)/σ; use the table or normalcdf; Empirical Rule 68–95–99.7.', 'z = (x−μ)/σ؛ استخدم الجدول أو التوزيع الطبيعي؛ القاعدة التجريبية 68–95–99.7.'),
 25: ('الدرجات والراديان وطول القوس وإزاحة الطور', 'Arc length s = rθ (θ in radians); π rad = 180°; phase shift = C in A sin(B(x−C)).', 'طول القوس s = rθ (θ بالراديان)؛ π راديان = 180°؛ إزاحة الطور = C في A sin(B(x−C)).'),
},
'12G': {
 1: ('خصائص منحنيات الدوال التربيعية', 'y=ax²+bx+c: axis x=−b/(2a); vertex on the axis; a>0 opens up (minimum), a<0 down (maximum).', 'y=ax²+bx+c: محور التماثل x=−b/(2a) والرأس عليه؛ a>0 فتحة لأعلى (صغرى) وa<0 لأسفل (عظمى).'),
 2: ('رسم الدوال التربيعية', 'Plot the vertex, the y-intercept and a mirror point, then draw the parabola through them.', 'عيّن الرأس والمقطع الصادي ونقطة مماثلة ثم ارسم القطع المكافئ.'),
 3: ('حل المعادلات التربيعية بيانياً', 'The real solutions of ax²+bx+c=0 are the x-intercepts of the graph.', 'الحلول الحقيقية للمعادلة ax²+bx+c=0 هي المقاطع السينية للمنحنى.'),
 4: ('حل المعادلات التربيعية بالتحليل', 'Factor, then use the zero-product property: each factor = 0.', 'حلّل ثم استخدم خاصية الضرب الصفري: كل عامل = 0.'),
 5: ('إكمال المربع في عبارة', 'x²+bx+(b/2)² = (x+b/2)². Add and subtract (b/2)².', 'x²+bx+(b/2)² = (x+b/2)². أضف واطرح (b/2)².'),
 6: ('القانون العام', 'x = (−b ± √(b²−4ac)) / (2a).', 'x = (−b ± √(b²−4ac)) / (2a).'),
 7: ('المميّز وطبيعة الجذور', 'D=b²−4ac: D>0 two real roots, D=0 one repeated root, D<0 no real roots.', 'D=b²−4ac: D>0 جذران حقيقيان، D=0 جذر مكرر، D<0 لا جذور حقيقية.'),
 8: ('المتباينات التربيعية بمتغيرين', 'Graph the boundary (dashed for < or >), then test a point to choose the shaded side.', 'ارسم الحد (متقطع للرمزين < و>) ثم اختبر نقطة لتحديد منطقة التظليل.'),
 9: ('تقييم وتحليل دوال كثيرات الحدود', 'Substitute the value (or use synthetic substitution); the degree and leading coefficient give the shape.', 'عوّض القيمة (أو التعويض التركيبي)؛ والدرجة والمعامل الرئيس يحددان الشكل.'),
 10: ('دوال القوى وسلوك الطرفين', 'Even degree: both ends the same direction; odd degree: opposite directions. The sign of the leading coefficient sets which.', 'درجة زوجية: الطرفان في الاتجاه نفسه؛ فردية: اتجاهان متعاكسان. وإشارة المعامل الرئيس تحدد الاتجاه.'),
 11: ('منحنيات كثيرات الحدود وأصفارها', 'Real zeros are x-intercepts; a factor (x−c)ⁿ crosses at c if n is odd and touches if n is even.', 'الأصفار الحقيقية هي المقاطع السينية؛ العامل (x−c)ⁿ يقطع المحور إذا كان n فردياً ويمسّه إذا كان زوجياً.'),
 12: ('القيم العظمى والصغرى النسبية', 'A relative maximum/minimum is a turning point where the graph changes direction.', 'القيمة العظمى/الصغرى النسبية نقطة انعطاف يتغير عندها اتجاه المنحنى.'),
 13: ('القسمة المطوّلة لكثيرات الحدود', 'Divide the leading terms, multiply back, subtract, bring down; repeat. Dividend = divisor × quotient + remainder.', 'اقسم الحدود الأولى واضرب واطرح وأنزل الحد التالي وكرّر. المقسوم = المقسوم عليه × الناتج + الباقي.'),
 14: ('القسمة التركيبية', 'For divisor x−c use c with the coefficients: bring down, multiply by c, add. The last number is the remainder.', 'للمقسوم عليه x−c استخدم c مع المعاملات: أنزل واضرب في c واجمع. آخر عدد هو الباقي.'),
 15: ('حل معادلات كثيرات الحدود بالتحليل', 'Move everything to one side, factor completely (GCF, grouping), set each factor to zero.', 'انقل كل الحدود لطرف واحد وحلّل تحليلاً كاملاً ثم ساوِ كل عامل بالصفر.'),
 16: ('منحنيات النمو الأسي', 'y=a·bˣ, b>1: a is the y-intercept and the x-axis is a horizontal asymptote.', 'y=a·bˣ مع b>1: a المقطع الصادي ومحور السينات خط تقارب أفقي.'),
 17: ('النمو والتضاؤل الأسي', 'y = a(1±r)ᵗ: growth uses 1+r, decay uses 1−r.', 'y = a(1±r)ᵗ: النمو 1+r والتضاؤل 1−r.'),
 18: ('أنواع الدراسات الإحصائية', 'Survey, observational study, experiment: an experiment assigns the treatment to subjects.', 'مسح، دراسة رصدية، تجربة: في التجربة تُعيَّن المعالجة للمشاركين.'),
 19: ('المعاينة والأسئلة المنحازة', 'A random sample represents the population; leading or loaded wording makes a question biased.', 'العينة العشوائية تمثل المجتمع؛ والصياغة الموجّهة تجعل السؤال منحازاً.'),
 20: ('القاعدة التجريبية والمساحات الطبيعية', 'About 68%, 95%, 99.7% of data lie within 1, 2, 3 standard deviations of the mean.', 'نحو 68% و95% و99.7% من البيانات ضمن 1 و2 و3 انحرافات معيارية من الوسط.'),
 21: ('حل المعادلات التربيعية بإكمال المربع', 'Move c, add (b/2)² to both sides, write (x+b/2)² = value, take square roots.', 'انقل c وأضف (b/2)² للطرفين واكتب (x+b/2)² = قيمة ثم خذ الجذر التربيعي.'),
 22: ('المتباينات التربيعية بمتغير واحد', 'Find the roots, split the number line, test a point in each interval.', 'أوجد الجذور وقسّم خط الأعداد واختبر نقطة في كل فترة.'),
 23: ('جمع وطرح وضرب كثيرات الحدود', 'Add/subtract like terms; multiply by distributing every term of one factor to the other.', 'اجمع/اطرح الحدود المتشابهة؛ واضرب بتوزيع كل حد من عامل على الآخر.'),
 24: ('حل المعادلات الأسية', 'Write both sides with the same base and equate the exponents.', 'اكتب الطرفين بالأساس نفسه وساوِ بين الأسس.'),
 25: ('الاحتمالات الطبيعية والقيم العكسية', 'z=(x−μ)/σ; read the area from the table; for an inverse value reverse the process.', 'z=(x−μ)/σ؛ اقرأ المساحة من الجدول؛ وللقيمة العكسية اعكس الخطوات.'),
},
'12A': {
 1: ('تقدير طول القوس', 'Approximate a curve by short straight segments and add their lengths; more segments give a better estimate.', 'قرّب المنحنى بقطع مستقيمة قصيرة واجمع أطوالها؛ كلما زادت القطع كان التقدير أدق.'),
 2: ('النهايات جبرياً وبيانياً', 'Evaluate by substitution, factoring/rationalising when 0/0, or read the value approached from the graph.', 'احسب بالتعويض أو بالتحليل/الترطيب عند 0/0 أو اقرأ القيمة المقتربة من الرسم.'),
 3: ('نظرية الحصر', 'If g(x) ≤ f(x) ≤ h(x) and lim g = lim h = L then lim f = L.', 'إذا كان g(x) ≤ f(x) ≤ h(x) وكانت نهايتا g وh تساويان L فإن نهاية f تساوي L.'),
 4: ('قوانين النهايات للدوال', 'Limits of sums, products and quotients are the sums, products and quotients of limits (denominator limit ≠ 0).', 'نهاية المجموع والضرب والقسمة هي مجموع وضرب وقسمة النهايات (ونهاية المقام ≠ 0).'),
 5: ('الاتصال عند نقطة', 'f is continuous at a if f(a) exists, lim f exists, and they are equal.', 'تكون f متصلة عند a إذا وُجدت f(a) ووُجدت النهاية وتساويتا.'),
 6: ('اتصال الدوال وتركيبها', 'Polynomials, rational functions (in their domain), trig and exponentials are continuous; compositions of continuous functions are continuous.', 'كثيرات الحدود والنسبية (في مجالها) والمثلثية والأسية متصلة؛ وتركيب الدوال المتصلة متصل.'),
 7: ('النهايات غير المنتهية والنهايات عند ∞', 'Divide by the highest power of x to evaluate limits at infinity; a zero denominator with non-zero numerator gives ±∞.', 'اقسم على أعلى قوة لـ x عند النهايات في ∞؛ ومقام صفري وبسط غير صفري يعطي ±∞.'),
 8: ('السرعة المتوسطة واللحظية', 'Average velocity = Δs/Δt; instantaneous velocity = lim of that as Δt→0 = s′(t).', 'السرعة المتوسطة = Δs/Δt؛ واللحظية = نهايتها عندما Δt→0 = s′(t).'),
 9: ('رسم دالة من منحنى مشتقتها', 'f′>0 where f increases, f′<0 where f decreases, f′=0 at flat points.', 'f′>0 حيث تتزايد f وf′<0 حيث تتناقص وf′=0 عند النقاط المسطحة.'),
 10: ('مشتقة دالة عند نقطة', 'f′(a) = lim (f(a+h)−f(a))/h, the slope of the tangent at x=a.', 'f′(a) = نهاية (f(a+h)−f(a))/h وهي ميل المماس عند x=a.'),
 11: ('قاعدة القوة للمشتقات', 'd/dx xⁿ = n·xⁿ⁻¹.', 'مشتقة xⁿ هي n·xⁿ⁻¹.'),
 12: ('قاعدتا الضرب والقسمة', '(fg)′=f′g+fg′; (f/g)′=(f′g−fg′)/g².', '(fg)′=f′g+fg′؛ (f/g)′=(f′g−fg′)/g².'),
 13: ('قاعدة السلسلة', '(f(g(x)))′ = f′(g(x))·g′(x): differentiate the outside, keep the inside, multiply by the derivative of the inside.', '(f(g(x)))′ = f′(g(x))·g′(x): اشتق الخارجية واترك الداخلية واضرب في مشتقة الداخلية.'),
 14: ('مشتقة الدالة العكسية', '(f⁻¹)′(b) = 1 / f′(a) where f(a)=b.', '(f⁻¹)′(b) = 1 / f′(a) حيث f(a)=b.'),
 15: ('مشتقات الدوال المثلثية', '(sin x)′=cos x, (cos x)′=−sin x, (tan x)′=sec²x.', '(sin x)′=cos x و(cos x)′=−sin x و(tan x)′=sec²x.'),
 16: ('مشتقات الدوال الأسية', '(eˣ)′=eˣ; (aˣ)′=aˣ ln a.', '(eˣ)′=eˣ؛ و(aˣ)′=aˣ ln a.'),
 17: ('مشتقات اللوغاريتم الطبيعي', '(ln x)′=1/x; (ln u)′=u′/u.', '(ln x)′=1/x؛ و(ln u)′=u′/u.'),
 18: ('الاشتقاق الضمني', 'Differentiate both sides with respect to x, treat y as y(x) (multiply by dy/dx), then solve for dy/dx.', 'اشتق الطرفين بالنسبة إلى x واعتبر y دالة في x (اضرب في dy/dx) ثم حل لإيجاد dy/dx.'),
 19: ('مشتقات الدوال المثلثية العكسية', '(sin⁻¹x)′=1/√(1−x²), (cos⁻¹x)′=−1/√(1−x²), (tan⁻¹x)′=1/(1+x²).', '(sin⁻¹x)′=1/√(1−x²) و(cos⁻¹x)′=−1/√(1−x²) و(tan⁻¹x)′=1/(1+x²).'),
 20: ('شروط نظرية رول', 'Rolle: f continuous on [a,b], differentiable on (a,b), f(a)=f(b) ⇒ f′(c)=0 for some c.', 'رول: f متصلة على [a,b] وقابلة للاشتقاق على (a,b) وf(a)=f(b) فيوجد c يحقق f′(c)=0.'),
 21: ('الاتصال: التعريف والتطبيقات', 'Choose constants so that the left limit, right limit and the value at the join are equal.', 'اختر الثوابت بحيث تتساوى النهاية من اليسار واليمين وقيمة الدالة عند نقطة الوصل.'),
 22: ('خطوط التقارب الأفقية والرأسية والمائلة', 'Vertical: zero of the denominator; horizontal/oblique: compare degrees at infinity.', 'الرأسي: صفر المقام؛ الأفقي/المائل: قارن الدرجات عند ∞.'),
 23: ('قاعدة الضرب', '(fg)′ = f′g + fg′. Simplify the result and evaluate at the requested point.', '(fg)′ = f′g + fg′. بسّط الناتج ثم عوّض عند النقطة المطلوبة.'),
 24: ('مشتقات الدوال المثلثية', 'Combine trig derivatives with product/quotient/chain rules; tangent line: y−f(a)=f′(a)(x−a).', 'اجمع مشتقات الدوال المثلثية مع قواعد الضرب والقسمة والسلسلة؛ المماس: y−f(a)=f′(a)(x−a).'),
 25: ('تطبيقات مشتقات الدوال الأسية واللوغاريتمية', 'Differentiate the model, then interpret f′(a) as the instantaneous rate of change with units.', 'اشتق النموذج ثم فسّر f′(a) معدل تغير لحظياً مع الوحدة.'),
 26: ('نظرية القيمة المتوسطة', 'MVT: f′(c) = (f(b)−f(a))/(b−a) for some c in (a,b) when f is continuous on [a,b] and differentiable on (a,b).', 'نظرية القيمة المتوسطة: f′(c) = (f(b)−f(a))/(b−a) لبعض c في (a,b) إذا كانت f متصلة على [a,b] وقابلة للاشتقاق على (a,b).'),
},
}
